// 每个玩家认领恰有自己的真实结果；同tick后来换控或裁剪缓存不改变原actor/请求/结果绑定。
#include "political_office_reception_receipts.hpp"
#include "resident/domains/organization/organization_office_history.hpp"
#include <map>
#include <set>
namespace hanmo::resident {namespace {
// 原本域来源全验与历史本人前置；此门只核实际永久提交元数据及仍保留的Common结果。
Status permanent(const CommonStore& c,const PoliticalOfficeReceptionState& state){
 if(state.version!=1||state.assignments.size()>4096)return common_failure("InvalidPoliticalOfficeReceptionLayout");std::map<StableId,Integer> requests;Integer last_result=0,last_revision=0;std::set<StableId> results;
 for(const auto& row:state.assignments.rows()){const auto& a=row.second;auto n=political_office_reception_fact_sequence(c,row.first);if(!n||a.id!=row.first||*n<=last_result||!a.player_receipt||a.tick<0||a.tick>c.tick())return common_failure("PoliticalOfficeReceptionPermanentResultRequired",row.first);const auto& b=*a.player_receipt;auto result=organization_instance_sequence(b.result_id,"result");const auto* request=c.state().request_sequences.find(a.actor_id);
  if(!result||*result<=*n||*result>=c.state().next_instance_id||!results.insert(b.result_id).second||b.actor_id!=a.actor_id||!request||b.request_sequence<1||b.request_sequence>2147483647||b.request_sequence>*request||b.request_sequence<=requests[a.actor_id]||b.result_revision<=last_revision||b.result_revision>c.revision())return common_failure("PoliticalOfficeReceptionResultBindingMismatch",a.id);
  for(const auto& head:c.state().facts.rows()){const auto at=head.first.rfind(':');auto allocated=at==StableId::npos?std::optional<Integer>{}:organization_instance_sequence(head.first,head.first.substr(0,at));if(allocated&&*allocated==*result)return common_failure("PoliticalOfficeReceptionResultFactCollision",a.id);}
  const HistoryRecord* previous=nullptr;Integer found=0;for(const auto& h:c.state().history){if(h.result_id==b.result_id){if(++found!=1||h.actor_id!=a.actor_id||h.kind!=political_office_reception_command||h.tick!=a.tick)return common_failure("PoliticalOfficeReceptionResultHistoryMismatch",a.id);if(previous){auto lower=organization_instance_sequence(previous->result_id,"result");if(!lower||*lower>=*n)return common_failure("PoliticalOfficeReceptionResultIntervalMismatch",a.id);}}previous=&h;}
  last_result=*result;last_revision=b.result_revision;requests[a.actor_id]=b.request_sequence;
 }
 for(const auto& h:c.state().history)if(h.kind==political_office_reception_command&&!results.count(h.result_id))return common_failure("PoliticalOfficeReceptionHistorySourceRequired",h.result_id);return common_success();
}
}
// 前后差分仅接可信本次writer，旧payload连同旧actualresult绑定必须逐字保留。
Outcome<StableId> political_office_reception_new_player_source(const PoliticalOfficeReceptionState& before,const PoliticalOfficeReceptionState& after,const StableId& actor,const StableId& kind,Integer tick){auto fail=[](){return Outcome<StableId>{false,{},common_failure("PoliticalOfficeReceptionNewSourceRequired").error};};if(kind!=political_office_reception_command||before.version!=1||after.version!=1||after.assignments.size()!=before.assignments.size()+1)return fail();for(const auto& row:before.assignments.rows())if(!row.second.player_receipt)return fail();const PoliticalOfficeReceptionAssignment* added=nullptr;for(const auto& row:after.assignments.rows())if(!before.assignments.find(row.first)){if(added||row.first!=row.second.id)return fail();added=&row.second;}if(!added||added->actor_id!=actor||added->tick!=tick||added->player_receipt)return fail();auto old=after;old.assignments.erase(added->id);if(!compare_boundary(encode_political_office_reception_state(before),encode_political_office_reception_state(old)).exact())return fail();return {true,added->id,{}};}
// 只在原result已经入cache/history的同候选提交尾写绑定；原Role已写但任何失败仍由外层回滚。
Status bind_political_office_reception_player_result(const CommonStore& c,PoliticalOfficeReceptionState& state,const StableId& id,const StableId& actor,Integer request,const CommitResult& result,const PoliticalOfficeReceptionResultMatch& match){const auto* a=state.assignments.find(id);const auto* cache=c.state().results.find(actor+":"+std::to_string(request));const auto* sequence=c.state().request_sequences.find(actor);if(!a||a->actor_id!=actor||a->tick!=result.tick||a->player_receipt||!result.ok||result.kind!=political_office_reception_command||result.tick!=c.tick()||result.revision!=c.revision()||!cache||cache->get()!=&result||!sequence||*sequence!=request||!match||!match(result,id)||c.state().history.empty())return common_failure("PoliticalOfficeReceptionActualResultRequired",id);const auto& h=c.state().history.back();if(h.result_id!=result.result_id||h.actor_id!=actor||h.kind!=result.kind||h.tick!=result.tick)return common_failure("PoliticalOfficeReceptionActualHistoryRequired",id);auto next=state;next.assignments.find(id)->player_receipt=PoliticalSuccessionPlayerReceipt{actor,result.result_id,request,result.revision};auto valid=permanent(c,next);if(!valid.ok)return valid;state=std::move(next);return common_success();}
// 裁剪后仍反查原永久绑定，不以同actor同tick最新剩余事实替换来源。
Status validate_political_office_reception_player_results(const CommonStore& c,const PoliticalOfficeReceptionState& state,const PoliticalOfficeReceptionResultMatch& match){auto valid=permanent(c,state);if(!valid.ok)return valid;std::set<StableId> used;for(const auto& row:c.state().results.rows()){if(!row.second||row.second->kind!=political_office_reception_command)continue;const auto& r=*row.second;const PoliticalOfficeReceptionAssignment* a=nullptr;for(const auto& source:state.assignments.rows())if(source.second.player_receipt&&source.second.player_receipt->result_id==r.result_id){if(a)return common_failure("PoliticalOfficeReceptionCachedSourceMismatch",row.first);a=&source.second;}if(!a||!r.ok||!match||!match(r,a->id)||r.tick!=a->tick||r.revision!=a->player_receipt->result_revision||row.first!=a->actor_id+":"+std::to_string(a->player_receipt->request_sequence)||!used.insert(a->id).second)return common_failure("PoliticalOfficeReceptionCachedSourceMismatch",row.first);if(std::count_if(c.state().history.begin(),c.state().history.end(),[&](const auto& h){return h.result_id==r.result_id;})!=1)return common_failure("PoliticalOfficeReceptionResultHistoryMismatch",row.first);}return common_success();}
}
